ntimeters();//\u5C06\u65F6\u95F4\u8F6C\u6362\u4E3A\u5398\u7C73\u3002\n    Serial.println("\u524D\u65B9\u969C\u788D\u7269\u7684\u8DDD\u79BB\u662F: ");\n    Serial.print(RangeInInches);//0~157\u82F1\u5BF8\n    Serial.println(" \u82F1\u5BF8");\n    Serial.print(RangeInCentimeters);//0~400\u5398\u7C73\n    Serial.println(" \u5398\u7C73");\n    delay(1000);\n}\n'})}),"\n",(0,t.jsx)(n.h2,{id:"\u6280\u672F\u652F\u6301\u4E0E\u4EA7\u54C1\u8BA8\u8BBA",children:"\u6280\u672F\u652F\u6301\u4E0E\u4EA7\u54C1\u8BA8\u8BBA"}),"\n",(0,t.jsxs)(n.p,{children:["\u5982\u679C\u60A8\u9047\u5230\u4EFB\u4F55\u6280\u672F\u95EE\u9898\uFF0C\u8BF7\u5C06\u95EE\u9898\u63D0\u4EA4\u5230\u6211\u4EEC\u7684 ",(0,t.jsx)(n.a,{href:"http://forum.seeedstudio.com/",children:"\u8BBA\u575B"}),"\u3002",(0,t.jsx)(n.br,{}),"\n","\u611F\u8C22\u60A8\u9009\u62E9\u6211\u4EEC\u7684\u4EA7\u54C1\uFF01\u6211\u4EEC\u81F4\u529B\u4E8E\u4E3A\u60A8\u63D0\u4F9B\u591A\u79CD\u652F\u6301\uFF0C\u4EE5\u786E\u4FDD\u60A8\u4F7F\u7528\u6211\u4EEC\u7684\u4EA7\u54C1\u65F6\u4F53\u9A8C\u987A\u7545\u3002\u6211\u4EEC\u63D0\u4F9B\u4E86\u591A\u4E2A\u6C9F\u901A\u6E20\u9053\uFF0C\u4EE5\u6EE1\u8DB3\u4E0D\u540C\u7684\u504F\u597D\u548C\u9700\u6C42\u3002"]}),"\n",(0,t.jsxs)("div",{class:"button_tech_support_container",children:[(0,t.jsx)("a",{href:"https://forum.seeedstudio.com/",class:"button_forum"}),(0,t.jsx)("a",{href:"https://www.seeedstudio.com/contacts",class:"button_email"})]}),"\n",(0,t.jsxs)("div",{class:"button_tech_support_container",children:[(0,t.jsx)("a",{href:"https://discord.gg/eWkprNDMU7",class:"button_discord"}),(0,t.jsx)("a",{href:"https://github.com/Seeed-Studio/wiki-documents/discussions/69",class:"button_discussion"})]})]})}function h(e={}){let{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,t.jsx)(n,{...e,children:(0,t.jsx)(a,{...e})}):a(e)}},71184(e,n,s){s.d(n,{R:()=>d,x:()=>l});var i=s(14041);let t={},r=i.createContext(t);function d(e){let n=i.useContext(r);return i.useMemo(function(){return"function"==typeof e?e(n):{